# Node.js + Express Auth Implementation

```javascript
// auth.js
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const app = express();

const SECRET = 'your-secret-key';
const SALT_ROUNDS = 10;

// In-memory storage (use DB in production)
const users = new Map();
const failedAttempts = new Map();
const RATE_LIMIT = { attempts: 5, windowMs: 15 * 60 * 1000 };

app.use(express.json());

// Rate limiting middleware
app.use('/auth/login', (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  if (!failedAttempts.has(ip)) failedAttempts.set(ip, []);

  const attempts = failedAttempts.get(ip).filter(t => now - t < RATE_LIMIT.windowMs);
  failedAttempts.set(ip, attempts);

  if (attempts.length >= RATE_LIMIT.attempts) {
    return res.status(429).json({ error: 'Too many login attempts. Try again later.' });
  }

  req.recordFailure = () => {
    failedAttempts.get(ip).push(now);
  };

  next();
});

// Signup
app.post('/auth/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password || password.length < 8) {
    return res.status(400).json({ error: 'Invalid email or password (min 8 chars)' });
  }

  if (users.has(email)) {
    return res.status(409).json({ error: 'Email already registered' });
  }

  try {
    const hashed = await bcrypt.hash(password, SALT_ROUNDS);
    users.set(email, { email, password: hashed, createdAt: new Date() });
    res.status(201).json({ message: 'Signup successful' });
  } catch (err) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

// Login
app.post('/auth/login', async (req, res) => {
  const { email, password } = req.body;
  const user = users.get(email);

  if (!user) {
    req.recordFailure();
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  try {
    const match = await bcrypt.compare(password, user.password);
    if (!match) {
      req.recordFailure();
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    failedAttempts.delete(req.ip);
    const token = jwt.sign({ email }, SECRET, { expiresIn: '24h' });
    res.json({ token, expiresIn: '24h' });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

// Protected route example
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/profile', authMiddleware, (req, res) => {
  res.json({ email: req.user.email });
});

app.listen(3000, () => console.log('Server on :3000'));
```

**Setup:**
```bash
npm install express bcrypt jsonwebtoken
node auth.js
```

**Usage:**
```bash
# Signup
curl -X POST http://localhost:3000/auth/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@test.com","password":"securepass123"}'

# Login
curl -X POST http://localhost:3000/auth/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@test.com","password":"securepass123"}'

# Protected endpoint (use token from login response)
curl http://localhost:3000/profile \
  -H "Authorization: Bearer <token>"
```

**Key points:**
- **bcrypt**: hashes passwords with salt rounds, resistant to rainbow tables
- **JWT**: stateless sessions, 24h expiry
- **Rate limiting**: 5 failed attempts per IP per 15 mins
- **Validation**: 8-char password minimum, email uniqueness check
- Timing-safe comparison via `bcrypt.compare()` prevents timing attacks

For production: replace in-memory storage with PostgreSQL, use Redis for rate limiting, add email verification, password reset flow, refresh tokens.
